import qrcode
import json
import uuid
import os

def generate_shell_execution_qr(output_filename="sh_executor_task.png"):
    """
    Generates a QR code that contains a shell script to be executed.
    The shell script creates a text file with 'Hello World' and a timestamp.
    """

    shell_script_content = (
        "#!/bin/bash\n"
        "# Shell script generated by QR task\n"
        "TIMESTAMP=$(/bin/date +\"%Y-%m-%d_%H-%M-%S\")\n"
        "FILENAME=\"hello_output_${TIMESTAMP}.txt\"\n"
        "echo \"Hello World - ${TIMESTAMP}\" > \"${FILENAME}\"\n"
        "echo \"Shell script executed. Created ${FILENAME}\"\n"
    )

    task_payload = {
        "task_id": str(uuid.uuid4()),
        "task_type": "execute_sh",
        "description": "QR task to create and execute a shell script for 'Hello World' output.",
        "script_content": shell_script_content
    }

    qr_data = json.dumps(task_payload, indent=2)

    img = qrcode.make(qr_data)
    img_path = os.path.join(os.getcwd(), output_filename)
    img.save(img_path)
    print(f"Shell execution QR code saved to: {img_path}")
    print("QR Data Payload:")
    print(qr_data)

if __name__ == "__main__":
    generate_shell_execution_qr()
